def reference(sequence, low, high, target):
    if not (0 <= high < len(sequence) and 0 <= low < len(sequence)):
        raise ValueError("invalid bounds")
    while high >= low:
        if sequence[low] == target:
            return low
        if sequence[high] == target:
            return high
        low += 1
        high -= 1
    return -1
